urlset:
{% set newest = (articles | first).date.date().isoformat() %}
  {{ SITEURL }}/{{ newest }}
  {{ SITEURL }}/blog/{{ newest }}
{% for page in pages if page.url %}
  {{ SITEURL }}/{{ page.url }}{% if page.modified or page.date %}{{ (page.modified or page.date).date().isoformat() }}{% endif %}
{% endfor %}
  {{ SITEURL }}/blog/etiquetas/{{ newest }}
{% for article in articles %}
  {{ SITEURL }}/{{ article.url }}{{ (article.modified or article.date).date().isoformat() }}
{% endfor %}
{% for tag, tagged in tags %}
  {{ SITEURL }}/{{ tag.url }}{{ (tagged | map(attribute="date") | max).date().isoformat() }}
{% endfor %}
